        } else if (stream.equalsIgnoreCase("Commerce")) {
            baseFee = 20000.0;
        } else if (stream.equalsIgnoreCase("Humanities")) {
            baseFee = 18000.0;
        }

        // Step 2: Hostel Add-on
        double hostelFee = 0.0;
        if (chkHostel.isSelected()) {
            hostelFee = 12000.0;
