public class BinarySearchDemo {
    public static void main(String[] args) {
        int[] arr = {10, 25, 38, 47, 59, 68, 77, 92};
        int key = 59;

        int low = 0;
        int high = arr.length - 1;
        int foundIndex = -1;

        while (low <= high) {
            int mid = low + (high - low) / 2;

            if (arr[mid] == key) {
                foundIndex = mid;
                break;
            } else if (arr[mid] < key) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (foundIndex != -1) {
            System.out.println("Key " + key + " found at index: " + foundIndex);
        } else {
            System.out.println("Key " + key + " not found.");
        }
    }
}
```

